N=22
grid=[[0]*N for _ in range(N)]
objs={
'9': {'shift':(14,7),'cells':[(2,1),(2,5),(3,1),(3,2),(3,3),(3,4),(3,5)],'marks':[(1,1),(1,5)]},
'8': {'shift':(2,1),'cells':[(3,16),(3,17),(3,18),(3,19),(4,19),(5,19),(6,16),(6,17),(6,18),(6,19)],'marks':[(3,15),(6,15)]},
'4': {'shift':(0,0),'cells':[(r,c) for r in range(8,11) for c in range(9,12)],'marks':[(7,10),(9,12),(11,9),(11,11)]},
'6': {'shift':(-9,8),'cells':[(13, c) for c in range(2,8)]+[(14,2),(14,7),(15,2),(15,7),(16,7),(17,7)]+[(18,c) for c in range(5,8)],'marks':[(14,8),(16,2),(17,8),(18,4)]},
'3': {'shift':(-6,-7),'cells':[(18,16),(18,18),(19,16),(19,18)]+[(20,c) for c in range(15,20)],'marks':[(17,16),(17,18),(21,15),(21,19)]}}
colors={'9':9,'8':8,'4':4,'6':6,'3':3}
collisions=[]
for k,o in objs.items():
 dr,dc=o['shift']
 for r,c in o['cells']:
  rr,cc=r+dr,c+dc
  if not(0<=rr<N and 0<=cc<N): print('out',k,rr,cc); continue
  if grid[rr][cc] not in (0,colors[k]): collisions.append((rr,cc,grid[rr][cc],colors[k]))
  grid[rr][cc]=colors[k]
for k,o in objs.items():
 dr,dc=o['shift']
 for r,c in o['marks']:
  rr,cc=r+dr,c+dc
  if grid[rr][cc] == 0: grid[rr][cc]=2
  elif grid[rr][cc] != 2: collisions.append(('mark',rr,cc,grid[rr][cc],k))
print('collisions',collisions)
print('\n'.join(' '.join(map(str,row)) for row in grid))
